/// <summary>
/// Extension of <c>PriceDiscAdmCheckPost</c> class
/// </summary>
[ExtensionOf(classStr(PriceDiscAdmCheckPost))]
final class GUPPriceDiscAdmCheckPost_Extension
{
    private boolean componentErrorFound;

}

Method.Source:
/// <summary>
/// Check journal when pricing attribute is enabled
/// </summary>
/// <param name = "_checkOnly">Check journal parameter</param>
/// <returns>True if journal should be validated; Otherwise false</returns>
protected boolean mustCheckJournal(boolean _checkOnly)
{
    boolean check = next mustCheckJournal(_checkOnly);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        check = PriceDiscAdmTable::find(journalNum).priceDiscPriceAttributeEnable() || check;
    }

    return check;
}

/// <summary>
/// Determines whether to check for overlaps and gaps.
/// </summary>
/// <param name = "_tempPriceDiscAdmTrans">The temp <c>PriceDiscAdmTrans</c> record.</param>
/// <param name = "_priceDiscAdmTrans">A <c>PriceDiscAdmTrans</c> record.</param>
/// <returns>true if the overlaps and gaps must be checked; otherwise, false.</returns>
protected boolean mustCheckForOverlapsAndGaps(PriceDiscAdmTrans _tempPriceDiscAdmTrans, PriceDiscAdmTrans _priceDiscAdmTrans)
{
    boolean check = next mustCheckForOverlapsAndGaps(_tempPriceDiscAdmTrans, _priceDiscAdmTrans);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        check = check && CustParameters::find().CheckForOverlapsAndGaps;
    }

    return check;
}

/// <summary>
/// Checks the journal lines.
/// </summary>
protected void checkJournalLines()
{
    next checkJournalLines();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        Query queryCheckJournal = this.buildCheckJournalLinesQuery();

        if (!queryCheckJournal)
        {
            return;
        }

        QueryRun queryRun = new QueryRun(queryCheckJournal);

        while (queryRun.next())
        {
            PriceDiscAdmTrans priceDiscAdmTrans = queryRun.get(tableNum(PriceDiscAdmTrans));

            if (!priceDiscAdmTrans.checkPriceComponent())
            {
                componentErrorFound = true;
            }
        }
    }
}

/// <summary>
///    Determines whether the price and discount agreement journal contains warnings.
/// </summary>
/// <param name="_acceptWarnings">
///    A Boolean value that specifies whether warnings are accepted; optional.
/// </param>
/// <returns>
///    true if only warnings are found; otherwise, false.
/// </returns>
public boolean checkJournal(boolean _acceptWarnings)
{
    boolean ret = next checkJournal(_acceptWarnings);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        ret = ret || componentErrorFound;
    }

    return ret;
}

/// <summary>
/// Adds the selection fields for journal check.
/// </summary>
/// <param name = "_priceDiscAdmTransSource">The <c>PriceDiscAdmTrans</c> data source.</param>
protected void addSelectionFieldsForCheckJournal(QueryBuildDataSource _priceDiscAdmTransSource)
{
    next addSelectionFieldsForCheckJournal(_priceDiscAdmTransSource);

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        _priceDiscAdmTransSource.addSelectionField(fieldNum(PriceDiscAdmTrans, PriceComponentCombination));
        _priceDiscAdmTransSource.addSelectionField(fieldNum(PriceDiscAdmTrans, PricingRuleHeader));
        _priceDiscAdmTransSource.addSelectionField(fieldNum(PriceDiscAdmTrans, PricingRuleLine));
        _priceDiscAdmTransSource.addSelectionField(fieldNum(PriceDiscAdmTrans, LineNum));
    }
}
